// Control de Retiros — API compartida sobre Cloudflare D1
// GET    /                     -> la página
// GET    /api/registros        -> lista todos los registros
// PUT    /api/registros/:id    -> crea o actualiza un registro
// DELETE /api/registros/:id    -> elimina un registro

const CAMPOS_TEXTO = ["embarque", "referencia", "almacenadora", "bodega", "fechaDocs", "fechaRetiro", "fechaDescarga", "creado", "actualizado"];
const FECHA = /^\d{4}-\d{2}-\d{2}$/;
const ID = /^[A-Za-z0-9_-]{1,64}$/;

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" },
  });
}

function limpiar(body) {
  const out = {};
  for (const k of CAMPOS_TEXTO) {
    const v = body[k];
    out[k] = typeof v === "string" ? v.trim().slice(0, 200) : "";
  }
  for (const k of ["fechaDocs", "fechaRetiro", "fechaDescarga"]) {
    if (out[k] && !FECHA.test(out[k])) out[k] = "";
  }
  out.tipo = body.tipo === "camion" || body.tipo === "contenedor" ? body.tipo : null;
  const n = Number(body.unidad);
  out.unidad = out.tipo && Number.isInteger(n) && n > 0 && n < 1000 ? n : null;
  out.descargado = body.descargado === true;
  if (!out.descargado) out.fechaDescarga = "";
  return out;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (!url.pathname.startsWith("/api/registros")) {
      if (request.method !== "GET" && request.method !== "HEAD") return new Response("Método no permitido", { status: 405 });
      return new Response(HTML, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache" } });
    }

    const partes = url.pathname.split("/").filter(Boolean); // ["api","registros",id?]
    const id = partes[2] ? decodeURIComponent(partes[2]) : null;
    // Si la app está protegida con Cloudflare Access, este encabezado trae el correo del usuario.
    const usuario = request.headers.get("Cf-Access-Authenticated-User-Email") || "";

    try {
      if (request.method === "GET" && !id) {
        const { results } = await env.DB.prepare("SELECT id, data, modificado_por FROM registros").all();
        return json(results.map((r) => ({ id: r.id, ...JSON.parse(r.data), modificadoPor: r.modificado_por || "" })));
      }

      if (request.method === "PUT" && id) {
        if (!ID.test(id)) return json({ error: "Identificador inválido" }, 400);
        let body;
        try { body = await request.json(); } catch { return json({ error: "JSON inválido" }, 400); }
        if (!body || typeof body !== "object") return json({ error: "Cuerpo inválido" }, 400);
        const reg = limpiar(body);
        if (!reg.referencia) return json({ error: "La referencia es obligatoria" }, 400);
        if (reg.tipo && !reg.fechaRetiro) return json({ error: "Falta la fecha de retiro" }, 400);
        const ahora = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO registros (id, data, actualizado, modificado_por) VALUES (?1, ?2, ?3, ?4)
           ON CONFLICT(id) DO UPDATE SET data = excluded.data, actualizado = excluded.actualizado, modificado_por = excluded.modificado_por`
        ).bind(id, JSON.stringify(reg), ahora, usuario).run();
        return json({ ok: true });
      }

      if (request.method === "DELETE" && id) {
        await env.DB.prepare("DELETE FROM registros WHERE id = ?1").bind(id).run();
        return json({ ok: true });
      }

      return json({ error: "Método no permitido" }, 405);
    } catch (e) {
      console.error(e);
      return json({ error: "Error del servidor" }, 500);
    }
  },
};

// ---------- Página (HTML incluido en este archivo) ----------
const HTML = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Control de Retiros</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Barlow+Condensed:wght@600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#E8E9EB; --panel:#FFFFFF; --panel-2:#F4F5F6; --ink:#1D2024; --muted:#5F656E;\n  --line:#D2D5D9; --red:#C8102E; --red-dk:#A00C24; --red-soft:#FBE8EB; --steel:#3B414A; --steel-soft:#E3E6EA;\n  --ok:#17784A; --ok-dk:#0F5C37; --ok-soft:#E2F4EA; --ok-line:#9CD4B5;\n  --font:\"Barlow\",-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif;\n  --cond:\"Barlow Condensed\",\"Arial Narrow\",Arial,sans-serif;\n  color-scheme:light; box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);\n}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\n*,*::before,*::after{box-sizing:inherit}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:15px;line-height:1.45;-webkit-text-size-adjust:100%}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--panel)}\nbutton,input,select{font:inherit;color:inherit}\n:focus-visible{outline:3px solid #F29AA8;outline-offset:2px}\n\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:6;background:var(--panel);border-bottom:3px solid var(--red)}\n.top-in{max-width:1180px;margin:0 auto;padding:12px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n.brand{display:flex;align-items:center;gap:10px;margin-right:auto}\n.brand h1{font-family:var(--cond);font-size:24px;margin:0;line-height:1}\n.sync{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px;font-weight:500}\n.sync i{width:8px;height:8px;border-radius:50%;background:#B8BCC2;display:inline-block}\n.sync.on i{background:var(--ok)}\n.nav{display:flex;gap:8px}\n\n.btn{appearance:none;border:2px solid var(--red);background:var(--red);color:#fff;font-weight:600;border-radius:8px;padding:9px 16px;cursor:pointer;min-height:42px;display:inline-flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap;transition:background .15s,transform .08s}\n.btn:hover{background:var(--red-dk);border-color:var(--red-dk)}\n.btn:active{transform:scale(.97)}\n.btn.ghost{background:transparent;color:var(--red)}\n.btn.ghost:hover{background:var(--red-soft)}\n.btn.sm{padding:5px 10px;min-height:34px;font-size:14px}\n.btn.plain{border-color:var(--line);background:var(--panel);color:var(--steel)}\n.btn.plain:hover{background:var(--panel-2)}\n.btn.green{background:var(--ok);border-color:var(--ok)}\n.btn.green:hover{background:var(--ok-dk);border-color:var(--ok-dk)}\n.btn[disabled]{opacity:.5;cursor:not-allowed}\n.icon-btn{appearance:none;border:0;background:transparent;color:var(--muted);padding:6px;border-radius:6px;cursor:pointer;min-width:36px;min-height:36px}\n.icon-btn:hover{background:var(--panel-2);color:var(--ink)}\n.icon-btn.del:hover{color:var(--red);background:var(--red-soft)}\n\nmain{max-width:1180px;margin:0 auto;padding:16px}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px}\n.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-bottom:12px}\n.toolbar .grow{flex:1 1 220px}\nlabel.f{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600;color:var(--steel)}\ninput[type=text],input[type=date],input[type=search],select{border:1px solid var(--line);background:var(--panel);border-radius:8px;padding:9px 10px;min-height:42px;width:100%;font-size:16px}\ninput:focus,select:focus{border-color:var(--red);outline:none;box-shadow:0 0 0 3px var(--red-soft)}\n\n/* Date chips */\n.chips{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 8px;margin-bottom:6px;scrollbar-width:thin}\n.chip{flex:none;appearance:none;border:1px solid var(--line);background:var(--panel);border-radius:10px;padding:7px 12px;cursor:pointer;text-align:left;min-width:96px;transition:border-color .15s,background .15s}\n.chip:hover{border-color:var(--red)}\n.chip b{display:block;font-family:var(--cond);font-size:18px;line-height:1.1}\n.chip span{display:block;white-space:nowrap;font-size:12px;color:var(--muted)}\n.chip .bar{display:block;height:4px;border-radius:2px;background:var(--steel-soft);margin-top:5px;overflow:hidden}\n.chip .bar i{display:block;height:100%;background:var(--ok)}\n.chip.on{background:var(--red);border-color:var(--red);color:#fff}\n.chip.on span{color:#FFE3E7}\n.chip.on .bar{background:rgba(255,255,255,.35)}\n.chip.on .bar i{background:#fff}\n\n/* Segmented status */\n.seg{display:inline-flex;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:3px;gap:3px;margin-bottom:12px;flex-wrap:wrap}\n.seg button{appearance:none;border:0;background:transparent;border-radius:7px;padding:7px 12px;cursor:pointer;font-weight:600;color:var(--steel);display:flex;align-items:center;gap:6px}\n.seg button em{font-style:normal;font-size:12px;background:var(--panel-2);border-radius:20px;padding:1px 7px;color:var(--muted)}\n.seg button.on{background:var(--red);color:#fff}\n.seg button.on em{background:rgba(255,255,255,.25);color:#fff}\n.seg button.on.okc{background:var(--ok)}\n.dot{width:9px;height:9px;border-radius:50%;display:inline-block}\n.dot.p{background:#B8BCC2}.dot.d{background:var(--ok)}\n.seg button.on .dot{background:#fff}\n.row-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:space-between}\n.legend{font-size:13px;color:var(--muted);display:flex;gap:14px;margin-bottom:12px;flex-wrap:wrap}\n.legend span{display:flex;align-items:center;gap:6px}\n.sw{width:14px;height:14px;border-radius:3px;display:inline-block;border:1px solid var(--line)}\n.sw.d{background:var(--ok-soft);border-color:var(--ok-line);box-shadow:inset 3px 0 0 var(--ok)}\n\n/* Day panel */\n.day{padding:14px 16px;margin-bottom:14px}\n.day-head{display:flex;flex-wrap:wrap;align-items:center;gap:8px 18px;margin-bottom:12px}\n.day-head h2{margin:0;font-family:var(--cond);font-size:22px;margin-right:auto}\n.day-nums{display:flex;gap:18px;flex-wrap:wrap}\n.num{display:flex;align-items:baseline;gap:6px;color:var(--muted);font-size:14px}\n.num b{font-family:var(--cond);font-size:28px;color:var(--ink);line-height:1}\n.num.red b{color:var(--red)} .num.okn b{color:var(--ok)}\n.units{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px}\n.unit{border:1px solid var(--line);border-top:4px solid var(--red);border-radius:9px;padding:10px 12px;background:var(--panel-2);display:flex;flex-direction:column;gap:8px;transition:border-color .2s}\n.unit.cont{border-top-color:var(--steel)}\n.unit.none{border-top-color:#B8BCC2;border-style:dashed;border-top-style:solid}\n.unit.full{border-color:var(--ok-line);border-top-color:var(--ok);background:var(--ok-soft)}\n.unit-h{display:flex;align-items:center;gap:8px}\n.unit-h h3{margin:0;font-size:15px;font-weight:700;margin-right:auto}\n.unit-h .ok{color:var(--ok);font-weight:700;font-size:13px}\n.prog{height:6px;border-radius:3px;background:var(--steel-soft);overflow:hidden}\n.prog i{display:block;height:100%;background:var(--ok);transition:width .35s ease}\n.pills{display:flex;flex-wrap:wrap;gap:6px}\n.pill{appearance:none;border:1px solid var(--line);background:var(--panel);border-radius:20px;padding:4px 10px 4px 8px;font-size:13px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:background .15s,border-color .15s,color .15s}\n.pill::before{content:\"\";width:12px;height:12px;border-radius:50%;border:2px solid #B8BCC2;box-sizing:border-box;flex:none}\n.pill:hover{border-color:var(--ok)}\n.pill.d{background:var(--ok);border-color:var(--ok);color:#fff}\n.pill.d::before{border-color:#fff;background:#fff;box-shadow:inset 0 0 0 2px var(--ok)}\n.unit .hint2{font-size:12px;color:var(--muted);margin:0}\n.dayb{appearance:none;text-align:left;cursor:pointer;font:inherit;color:inherit}\n.dayb:hover{border-color:var(--red)}\n.toolbar label.f.dt{flex:1 1 140px;max-width:200px}\n\n.selbar{position:sticky;bottom:calc(10px + env(safe-area-inset-bottom,0px));z-index:4;display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:var(--ink);color:#fff;border-radius:10px;padding:10px 14px;margin:12px 0;box-shadow:0 6px 20px rgba(20,22,26,.25)}\n.selbar>span{margin-right:auto;font-weight:600}\n.selbar .btn.plain{background:transparent;color:#fff;border-color:#5B616A}\n\n/* Table */\n.tbl-wrap{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth,td{text-align:left;padding:10px 10px;border-bottom:1px solid var(--line);vertical-align:middle}\nth{font-size:12.5px;color:var(--muted);font-weight:600;background:var(--panel-2);white-space:nowrap}\nth[data-sort]{cursor:pointer;user-select:none}\nth[data-sort]:hover{color:var(--ink)}\nth .ar{font-size:10px;margin-left:3px;color:var(--red)}\ntr:last-child td{border-bottom:0}\ntbody tr{transition:background .25s}\ntbody tr:hover td{background:#FAFAFB}\ntbody tr.d td{background:var(--ok-soft)}\ntbody tr.d td:first-child{box-shadow:inset 4px 0 0 var(--ok)}\ntbody tr.d:hover td{background:#D6EFE1}\ntbody tr.click{cursor:pointer}\ntd.n,th.n{text-align:right;font-variant-numeric:tabular-nums}\ntr.total td{font-weight:700;background:var(--panel-2)}\n.ref{font-weight:700}\n.chk{width:20px;height:20px;accent-color:var(--red);cursor:pointer}\n.tag{display:inline-block;font-family:var(--cond);font-weight:600;font-size:14px;padding:2px 8px;border-radius:5px;white-space:nowrap}\n.tag.cam{background:var(--red-soft);color:var(--red-dk)}\n.tag.cont{background:var(--steel-soft);color:var(--steel)}\n.tag.none{color:var(--muted);font-family:var(--font);font-size:13px;font-weight:500}\n.st{appearance:none;border:1px solid var(--line);background:var(--panel);color:var(--steel);border-radius:20px;padding:5px 12px 5px 9px;font-size:13px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;transition:all .15s}\n.st::before{content:\"\";width:14px;height:14px;border-radius:50%;border:2px solid #B8BCC2;box-sizing:border-box}\n.st:hover{border-color:var(--ok);color:var(--ok)}\n.st.d{background:var(--ok);border-color:var(--ok);color:#fff}\n.st.d::before{content:\"✓\";border:0;background:#fff;color:var(--ok);font-size:10px;line-height:14px;text-align:center;font-weight:700}\n.st small{font-weight:500;opacity:.85}\n.empty{padding:36px 16px;text-align:center;color:var(--muted)}\n.empty strong{display:block;color:var(--ink);font-size:17px;margin-bottom:4px}\n\n.cards{display:none}\n.card{padding:12px 14px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:auto 1fr auto;gap:6px 12px;align-items:start;transition:background .25s}\n.card:last-child{border-bottom:0}\n.card.d{background:var(--ok-soft);box-shadow:inset 4px 0 0 var(--ok)}\n.card .meta{grid-column:2/4;display:grid;grid-template-columns:1fr 1fr;gap:2px 12px;font-size:13px;color:var(--muted)}\n.card .meta b{color:var(--ink);font-weight:500}\n.card .stw{grid-column:2/4}\n.card .stw .st{width:100%;justify-content:center;padding:9px 12px;font-size:14px}\n.card .acts{display:flex}\n@media (max-width:760px){\n  .tbl-wrap.records{display:none}\n  .cards{display:block}\n  .top-in{padding:10px 12px}\n  main{padding:12px}\n  .nav{width:100%}\n  .nav .btn{flex:1}\n  .brand h1{font-size:21px}\n  .seg{display:flex;width:100%}\n  .seg button{flex:1;justify-content:center;padding:7px 6px}\n}\n@media (prefers-reduced-motion:no-preference){\n  .flash td,.card.flash{animation:flash .9s ease-out}\n  @keyframes flash{0%{background:#B9E6CC}100%{}}\n  .modal{animation:pop .16s ease-out}\n  @keyframes pop{from{transform:translateY(8px);opacity:.6}}\n  .kpi b{animation:rise .4s ease-out}\n  @keyframes rise{from{opacity:.2;transform:translateY(4px)}}\n}\n\n/* Stats */\n.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:14px}\n.kpi{padding:12px 14px;position:relative;overflow:hidden}\n.kpi b{display:block;font-family:var(--cond);font-size:36px;line-height:1.05}\n.kpi span{color:var(--muted);font-size:13.5px}\n.kpi.red b{color:var(--red)} .kpi.okk b{color:var(--ok)}\n.kpi .prog{margin-top:8px}\n@media (max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.kpi.wide{grid-column:1/-1}}\n.sect{margin-bottom:16px}\n.sect-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px 10px}\n.sect-h h2{font-family:var(--cond);font-size:21px;margin:0;margin-right:auto}\n.sect-h small{color:var(--muted);font-size:12.5px}\n.note{font-size:12.5px;color:var(--muted);padding:8px 14px 12px;margin:0}\n.qr{display:flex;gap:6px;flex-wrap:wrap}\n.qr button{appearance:none;border:1px solid var(--line);background:var(--panel);border-radius:20px;padding:6px 12px;font-weight:600;font-size:13px;cursor:pointer;color:var(--steel)}\n.qr button.on{background:var(--red);border-color:var(--red);color:#fff}\n\n.chart{overflow-x:auto;padding:4px 14px 6px}\n.bars{display:flex;align-items:flex-end;gap:10px;height:190px;min-width:min-content;padding-top:22px;border-bottom:1px solid var(--line)}\n.bcol{appearance:none;border:0;background:transparent;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;width:46px;flex:none;cursor:pointer;position:relative}\n.bcol .v{font-family:var(--cond);font-size:15px;font-weight:700;margin-bottom:3px}\n.bstack{width:30px;display:flex;flex-direction:column-reverse;border-radius:5px 5px 0 0;overflow:hidden;transition:height .4s ease}\n.bstack i{display:block;width:100%}\n.bstack .c1{background:var(--red)} .bstack .c2{background:var(--steel)}\n.bcol:hover .bstack{filter:brightness(1.12)}\n.bcol:hover .v{color:var(--red)}\n.blab{display:flex;gap:10px;min-width:min-content}\n.blab span{width:46px;flex:none;text-align:center;font-size:12px;color:var(--muted);padding-top:4px}\n.ckey{display:flex;gap:14px;font-size:12.5px;color:var(--muted);padding:6px 14px 12px}\n.ckey span{display:flex;align-items:center;gap:5px}\n.ckey i{width:11px;height:11px;border-radius:2px;display:inline-block}\n.tip{position:fixed;z-index:25;background:var(--ink);color:#fff;font-size:13px;padding:7px 10px;border-radius:7px;pointer-events:none;max-width:220px;line-height:1.35}\n.minibar{display:inline-block;vertical-align:middle;height:8px;border-radius:4px;background:var(--red);margin-right:8px;transition:width .35s}\n.pct{display:inline-flex;align-items:center;gap:6px;justify-content:flex-end}\n.pct .prog{width:60px;display:inline-block}\n\n/* Modal */\n.ov{position:fixed;inset:0;background:rgba(25,28,33,.5);z-index:20;display:flex;align-items:center;justify-content:center;padding:16px}\n.modal{background:var(--panel);border-radius:12px;width:100%;max-width:640px;max-height:calc(100% - 20px);overflow:auto;box-shadow:0 18px 50px rgba(0,0,0,.3)}\n.modal header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--panel);z-index:1}\n.modal header h2{margin:0;font-family:var(--cond);font-size:22px}\n.modal .body{padding:16px 18px;display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.modal .body .full{grid-column:1/-1}\n.modal footer{display:flex;gap:10px;justify-content:flex-end;padding:12px 18px 16px;border-top:1px solid var(--line);position:sticky;bottom:0;background:var(--panel);flex-wrap:wrap}\n.fieldset{grid-column:1/-1;border:1px solid var(--line);border-radius:10px;padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:12px;background:var(--panel-2)}\n.fieldset.okf{background:var(--ok-soft);border-color:var(--ok-line)}\n.fieldset legend{font-weight:700;font-size:14px;padding:0 6px}\n.switch{display:flex;align-items:center;gap:10px;font-weight:600;cursor:pointer;align-self:end;min-height:42px}\n.switch input{width:22px;height:22px;accent-color:var(--ok)}\n.hint{grid-column:1/-1;font-size:13px;color:var(--muted);margin:0}\n.err{grid-column:1/-1;color:var(--red-dk);background:var(--red-soft);border-radius:8px;padding:8px 10px;font-size:14px;margin:0}\n@media (max-width:760px){\n  .ov{align-items:flex-end;padding:0}\n  .modal{border-radius:14px 14px 0 0;max-height:92%;padding-bottom:env(safe-area-inset-bottom,0px)}\n  .modal .body,.fieldset{grid-template-columns:1fr}\n}\n.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 16px;border-radius:8px;z-index:30;font-size:14px;max-width:90%;display:flex;gap:12px;align-items:center}\n.toast button{appearance:none;border:0;background:transparent;color:#FF8A9C;font-weight:700;cursor:pointer;padding:2px 4px}\n.hidden{display:none!important}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <div class=\"top-in\">\n    <div class=\"brand\">\n      <svg width=\"34\" height=\"34\" viewBox=\"0 0 34 34\" aria-hidden=\"true\"><rect width=\"34\" height=\"34\" rx=\"7\" fill=\"#C8102E\"/><path d=\"M6 21V11h13v10M19 14h5l4 4v3h-9\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/><circle cx=\"11\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/><circle cx=\"24\" cy=\"23\" r=\"2.4\" fill=\"#fff\"/></svg>\n      <div><h1>Control de Retiros</h1><small class=\"sync\" id=\"sync\"><i></i><span>Conectando…</span></small></div>\n    </div>\n    <nav class=\"nav\">\n      <button class=\"btn\" id=\"nav-reg\" type=\"button\">Registros</button>\n      <button class=\"btn ghost\" id=\"nav-est\" type=\"button\">Estadísticas</button>\n    </nav>\n  </div>\n</header>\n\n<main>\n  <section id=\"v-reg\">\n    <div class=\"toolbar\">\n      <button class=\"btn\" id=\"btn-new\" type=\"button\">+ Nuevo registro</button>\n      <label class=\"f grow\">Buscar\n        <input type=\"search\" id=\"q\" placeholder=\"Embarque, referencia, almacenadora, bodega…\">\n      </label>\n      <label class=\"f dt\">Retiro desde\n        <input type=\"date\" id=\"fdate\">\n      </label>\n      <label class=\"f dt\">Hasta\n        <input type=\"date\" id=\"fhasta\">\n      </label>\n      <button class=\"btn ghost\" id=\"btn-hoy\" type=\"button\">Hoy</button>\n      <button class=\"btn plain\" id=\"btn-clear\" type=\"button\">Todas las fechas</button>\n    </div>\n    <div class=\"row-tools\">\n      <div class=\"seg\" id=\"seg\" role=\"tablist\" aria-label=\"Estado\"></div>\n      <div class=\"legend\"><span><i class=\"sw d\"></i>Descargado en CD</span><span><i class=\"sw\"></i>Pendiente de descarga</span></div>\n    </div>\n    <div id=\"day\"></div>\n    <div id=\"selbar\" class=\"selbar hidden\">\n      <span id=\"selcount\"></span>\n      <button class=\"btn sm green\" id=\"btn-markd\" type=\"button\">✓ Marcar descargadas</button>\n      <button class=\"btn sm\" id=\"btn-assign\" type=\"button\">Asignar transporte</button>\n      <button class=\"btn sm plain\" id=\"btn-markp\" type=\"button\">Marcar pendientes</button>\n      <button class=\"btn sm plain\" id=\"btn-unsel\" type=\"button\">Quitar selección</button>\n    </div>\n    <div class=\"panel\">\n      <div class=\"tbl-wrap records\"><table id=\"tbl\"></table></div>\n      <div class=\"cards\" id=\"cards\"></div>\n    </div>\n  </section>\n\n  <section id=\"v-est\" class=\"hidden\">\n    <div class=\"toolbar\">\n      <label class=\"f\">Desde (retiro)<input type=\"date\" id=\"s-from\"></label>\n      <label class=\"f\">Hasta (retiro)<input type=\"date\" id=\"s-to\"></label>\n      <div class=\"qr\" id=\"qr\" style=\"align-self:center\">\n        <button type=\"button\" data-range=\"7\">Últimos 7 días</button>\n        <button type=\"button\" data-range=\"30\">Últimos 30 días</button>\n        <button type=\"button\" data-range=\"mes\">Este mes</button>\n        <button type=\"button\" data-range=\"all\">Todo</button>\n      </div>\n      <button class=\"btn ghost hidden\" id=\"s-csv\" type=\"button\" style=\"margin-left:auto\">Exportar CSV</button>\n    </div>\n    <div class=\"kpis\" id=\"kpis\"></div>\n    <div class=\"panel sect\">\n      <div class=\"sect-h\"><h2>Unidades por fecha de retiro</h2><small>Toca una barra para ver ese día</small></div>\n      <div class=\"chart\" id=\"chart\"></div>\n      <div class=\"ckey\"><span><i style=\"background:var(--red)\"></i>Camiones 8 ton</span><span><i style=\"background:var(--steel)\"></i>Contenedores</span></div>\n    </div>\n    <div class=\"panel sect\"><div class=\"sect-h\"><h2>Por fecha de retiro</h2><small>Toca una fila para ver el detalle</small></div><div class=\"tbl-wrap\"><table id=\"t-fecha\"></table></div></div>\n    <div class=\"panel sect\"><div class=\"sect-h\"><h2>Por almacenadora</h2></div><div class=\"tbl-wrap\"><table id=\"t-alm\"></table></div>\n      <p class=\"note\">Una unidad que llevó referencias de varias almacenadoras cuenta una vez en cada una; por eso la suma de unidades puede superar el total general.</p></div>\n    <div class=\"panel sect\"><div class=\"sect-h\"><h2>Por bodega</h2></div><div class=\"tbl-wrap\"><table id=\"t-bod\"></table></div>\n      <p class=\"note\">Misma regla: una unidad compartida entre bodegas se cuenta en cada bodega que atendió.</p></div>\n  </section>\n</main>\n\n<div id=\"modal-root\"></div>\n<datalist id=\"dl-alm\"></datalist>\n<datalist id=\"dl-bod\"></datalist>\n\n<script>\n(function(){\n  \"use strict\";\n  var regs = [], sel = new Set(), flash = new Set();\n  var view = \"reg\", stFilter = \"all\", sortKey = \"fechaRetiro\", sortDir = -1, qRange = \"all\";\n  var store = { mode: \"loading\" }, downloads = null;\n  var LS_KEY = \"control_retiros_v1\";\n\n  var $ = function(id){ return document.getElementById(id); };\n  function esc(s){ return String(s == null ? \"\" : s).replace(/[&<>\"']/g, function(c){ return {\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]; }); }\n  function fmt(d){ if(!d) return \"—\"; var p = d.split(\"-\"); return p.length===3 ? p[2]+\"/\"+p[1]+\"/\"+p[0] : d; }\n  function fmtShort(d){ var p = (d||\"\").split(\"-\"); return p.length===3 ? p[2]+\"/\"+p[1] : d; }\n  function today(off){ var d=new Date(); d.setDate(d.getDate()+(off||0)); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,10); }\n  function newId(){ return \"r\" + Date.now().toString(36) + Math.random().toString(36).slice(2,8); }\n  function unitKey(r){ return (r.fechaRetiro && r.tipo && r.unidad) ? r.fechaRetiro+\"|\"+r.tipo+\"|\"+r.unidad : null; }\n  function unitLabel(tipo, n){ return (tipo===\"camion\" ? \"Camión 8 ton\" : \"Contenedor\") + \" #\" + n; }\n  function tagHtml(r){\n    if(!r.tipo || !r.unidad) return '<span class=\"tag none\">Sin asignar</span>';\n    return '<span class=\"tag '+(r.tipo===\"camion\"?\"cam\":\"cont\")+'\">'+esc(unitLabel(r.tipo, r.unidad))+'</span>';\n  }\n  function stHtml(r){\n    return r.descargado\n      ? '<button class=\"st d\" type=\"button\" data-desc=\"'+esc(r.id)+'\" title=\"Toca para marcar como pendiente\">Descargado'+(r.fechaDescarga?' <small>'+esc(fmtShort(r.fechaDescarga))+'</small>':'')+'</button>'\n      : '<button class=\"st\" type=\"button\" data-desc=\"'+esc(r.id)+'\" title=\"Toca para confirmar la descarga en CD\">Confirmar descarga</button>';\n  }\n  var toastTimer;\n  function toast(msg, undo){\n    var old = document.querySelector(\".toast\"); if(old) old.remove();\n    var t = document.createElement(\"div\"); t.className=\"toast\";\n    var s = document.createElement(\"span\"); s.textContent = msg; t.appendChild(s);\n    if(undo){ var b=document.createElement(\"button\"); b.type=\"button\"; b.textContent=\"Deshacer\"; b.onclick=function(){ t.remove(); undo(); }; t.appendChild(b); }\n    document.body.appendChild(t); clearTimeout(toastTimer); toastTimer = setTimeout(function(){ t.remove(); }, undo?5000:2800);\n  }\n\n  /* ---------- Storage (API compartida en Cloudflare) ---------- */\n  var API = \"/api/registros\", busy = 0;\n  function setSync(text, on){ var s=$(\"sync\"); s.querySelector(\"span\").textContent=text; s.classList.toggle(\"on\", !!on); }\n  function bodyOf(r){ var b = Object.assign({}, r); delete b.id; delete b.modificadoPor; return b; }\n  function hora(){ var d=new Date(); return String(d.getHours()).padStart(2,\"0\")+\":\"+String(d.getMinutes()).padStart(2,\"0\"); }\n\n  async function api(method, path, body){\n    var res = await fetch(path, { method: method, headers: body ? {\"Content-Type\":\"application/json\"} : {}, body: body ? JSON.stringify(body) : undefined, credentials: \"same-origin\" });\n    if(!res.ok){\n      var msg = \"Error \" + res.status;\n      try{ var j = await res.json(); if(j && j.error) msg = j.error; }catch(e){}\n      var err = new Error(msg); err.status = res.status; throw err;\n    }\n    return res.json();\n  }\n\n  async function load(silent){\n    if(busy) return;\n    try{\n      var data = await api(\"GET\", API);\n      if(busy) return;\n      regs = Array.isArray(data) ? data : [];\n      store.mode = \"api\";\n      setSync(\"Compartido · actualizado \" + hora(), true);\n      render();\n    }catch(e){\n      setSync(\"Sin conexión con el servidor\", false);\n      if(!silent) toast(\"No se pudieron cargar los registros.\");\n    }\n  }\n\n  function put(id, body){\n    busy++;\n    var i = regs.findIndex(function(r){ return r.id===id; });\n    var prev = i>=0 ? regs[i] : null;\n    var rec = Object.assign({ id:id }, body);\n    if(i>=0) regs[i]=rec; else regs.push(rec);\n    render();\n    return api(\"PUT\", API + \"/\" + encodeURIComponent(id), body).then(function(){\n      busy--; setSync(\"Compartido · actualizado \" + hora(), true);\n    }).catch(function(e){\n      busy--;\n      var j = regs.findIndex(function(r){ return r.id===id; });\n      if(prev) regs[j] = prev; else if(j>=0) regs.splice(j,1);\n      render();\n      toast(e.status===401||e.status===403 ? \"No tienes permiso para editar.\" : \"No se pudo guardar: \" + e.message);\n      throw e;\n    });\n  }\n  function del(id){\n    busy++;\n    var prev = regs.slice();\n    regs = regs.filter(function(r){ return r.id!==id; }); render();\n    return api(\"DELETE\", API + \"/\" + encodeURIComponent(id)).then(function(){ busy--; }).catch(function(){\n      busy--; regs = prev; render(); toast(\"No se pudo eliminar.\");\n    });\n  }\n\n  async function initStore(){\n    $(\"s-csv\").classList.remove(\"hidden\");\n    await load(false);\n    setInterval(function(){ if(!document.hidden && !$(\"modal-root\").innerHTML) load(true); }, 15000);\n    document.addEventListener(\"visibilitychange\", function(){ if(!document.hidden) load(true); });\n  }\n\n  /* ---------- Descarga ---------- */\n  async function setDescargado(ids, val, silent){\n    var prev = [];\n    ids.forEach(function(id){ var r = regs.find(function(x){ return x.id===id; }); if(r) prev.push({id:id, d:!!r.descargado, f:r.fechaDescarga||\"\"}); });\n    var targets = prev.filter(function(p){ return p.d !== val; });\n    if(!targets.length) return;\n    targets.forEach(function(p){ flash.add(p.id); });\n    try{\n      for(var i=0;i<targets.length;i++){\n        var r = regs.find(function(x){ return x.id===targets[i].id; }); if(!r) continue;\n        var b = bodyOf(r); b.descargado = val; b.fechaDescarga = val ? (r.fechaDescarga || today()) : \"\"; b.actualizado = new Date().toISOString();\n        await put(r.id, b);\n      }\n    }catch(e){ return; }\n    setTimeout(function(){ flash.clear(); }, 950);\n    if(!silent){\n      var n = targets.length;\n      toast((n===1 ? \"Referencia \" : n+\" referencias \") + (val ? \"confirmada\"+(n>1?\"s\":\"\")+\" como descargada\"+(n>1?\"s\":\"\")+\" en CD\" : \"marcada\"+(n>1?\"s\":\"\")+\" como pendiente\"+(n>1?\"s\":\"\")),\n        function(){\n          (async function(){\n            for(var i=0;i<targets.length;i++){\n              var r = regs.find(function(x){ return x.id===targets[i].id; }); if(!r) continue;\n              var b = bodyOf(r); b.descargado = targets[i].d; b.fechaDescarga = targets[i].f; b.actualizado = new Date().toISOString();\n              try{ await put(r.id, b); }catch(e){ return; }\n            }\n          })();\n        });\n    }\n  }\n\n  /* ---------- Units helpers ---------- */\n  function unitsFor(fecha, tipo){\n    var m = {};\n    regs.forEach(function(r){ if(r.fechaRetiro===fecha && r.tipo===tipo && r.unidad){ (m[r.unidad] = m[r.unidad] || []).push(r); } });\n    var nums = Object.keys(m).map(Number).sort(function(a,b){ return a-b; });\n    return { list: nums.map(function(n){ return { n:n, refs:m[n] }; }), next: nums.length ? nums[nums.length-1]+1 : 1 };\n  }\n  function unitOptions(fecha, tipo, current){\n    var u = unitsFor(fecha, tipo);\n    var last = u.list.length ? u.list[u.list.length-1].n : null;\n    var pick = current ? current : last;\n    var html = u.list.map(function(x){\n      return '<option value=\"'+x.n+'\"'+(String(pick)===String(x.n)?\" selected\":\"\")+'>Sumar a '+esc(unitLabel(tipo,x.n))+' (lleva '+x.refs.length+' ref.)</option>';\n    }).join(\"\");\n    html += '<option value=\"new\"'+(!pick?\" selected\":\"\")+'>Nueva unidad: '+esc(unitLabel(tipo,u.next))+'</option>';\n    return html;\n  }\n\n  /* ---------- Records view ---------- */\n  function baseFiltered(){\n    var q = $(\"q\").value.trim().toLowerCase(), f = $(\"fdate\").value, h = $(\"fhasta\").value;\n    return regs.filter(function(r){\n      if((f || h) && !r.fechaRetiro) return false;\n      if(f && r.fechaRetiro < f) return false;\n      if(h && r.fechaRetiro > h) return false;\n      if(!q) return true;\n      return [r.embarque,r.referencia,r.almacenadora,r.bodega].some(function(v){ return (v||\"\").toLowerCase().indexOf(q) >= 0; });\n    });\n  }\n  function filtered(){\n    var rows = baseFiltered().filter(function(r){\n      return stFilter===\"all\" || (stFilter===\"d\" ? !!r.descargado : !r.descargado);\n    });\n    var k = sortKey;\n    return rows.sort(function(a,b){\n      var va, vb;\n      if(k===\"transporte\"){ va=(a.tipo||\"~\")+String(a.unidad||0).padStart(3,\"0\"); vb=(b.tipo||\"~\")+String(b.unidad||0).padStart(3,\"0\"); }\n      else if(k===\"estado\"){ va=a.descargado?1:0; vb=b.descargado?1:0; }\n      else { va=(a[k]||\"\").toString().toLowerCase(); vb=(b[k]||\"\").toString().toLowerCase(); }\n      if(va===vb){ return (a.referencia||\"\").localeCompare(b.referencia||\"\"); }\n      if(va===\"\"||va==null) return 1; if(vb===\"\"||vb==null) return -1;\n      return (va<vb?-1:1)*sortDir;\n    });\n  }\n\n  function renderChips(){\n    var m = {};\n    regs.forEach(function(r){ if(!r.fechaRetiro) return; var g = m[r.fechaRetiro] || (m[r.fechaRetiro]={refs:0,d:0,cam:new Set(),cont:new Set()}); g.refs++; if(r.descargado) g.d++; var uk=unitKey(r); if(uk)(r.tipo===\"camion\"?g.cam:g.cont).add(uk); });\n    var dates = Object.keys(m).sort().reverse().slice(0,21);\n    var cur = $(\"fdate\").value;\n    if(!dates.length){ $(\"chips\").innerHTML=\"\"; $(\"chips\").classList.add(\"hidden\"); return; }\n    $(\"chips\").classList.remove(\"hidden\");\n    $(\"chips\").innerHTML = '<button type=\"button\" class=\"chip'+(!cur?\" on\":\"\")+'\" data-chip=\"\"><b>Todas</b><span>'+regs.length+' ref.</span><span>'+regs.filter(function(r){return r.descargado;}).length+'/'+regs.length+' descargadas</span><span class=\"bar\"><i style=\"width:'+(regs.length?Math.round(regs.filter(function(r){return r.descargado;}).length/regs.length*100):0)+'%\"></i></span></button>' +\n      dates.map(function(d){\n        var g = m[d], parts = [];\n        if(g.cam.size) parts.push(g.cam.size+(g.cam.size===1?\" camión\":\" camiones\"));\n        if(g.cont.size) parts.push(g.cont.size+(g.cont.size===1?\" contenedor\":\" contenedores\"));\n        parts.push(g.refs+\" ref.\");\n        return '<button type=\"button\" class=\"chip'+(cur===d?\" on\":\"\")+'\" data-chip=\"'+d+'\" title=\"'+g.d+' de '+g.refs+' descargadas\"><b>'+esc(fmtShort(d))+'</b><span>'+esc(parts.join(\" · \"))+'</span><span>'+g.d+'/'+g.refs+' descargadas</span><span class=\"bar\"><i style=\"width:'+Math.round(g.d/g.refs*100)+'%\"></i></span></button>';\n      }).join(\"\");\n  }\n\n  function renderSeg(){\n    var base = baseFiltered(), d = base.filter(function(r){ return r.descargado; }).length;\n    var opts = [[\"all\",\"Todas\",base.length,\"\"],[\"p\",\"Pendientes\",base.length-d,'<i class=\"dot p\"></i>'],[\"d\",\"Descargadas\",d,'<i class=\"dot d\"></i>']];\n    $(\"seg\").innerHTML = opts.map(function(o){\n      return '<button type=\"button\" role=\"tab\" data-st=\"'+o[0]+'\" class=\"'+(stFilter===o[0]?\"on\":\"\")+(o[0]===\"d\"?\" okc\":\"\")+'\" aria-selected=\"'+(stFilter===o[0])+'\">'+o[3]+o[1]+' <em>'+o[2]+'</em></button>';\n    }).join(\"\");\n  }\n\n  function renderRange(f, h, box){\n    var rs = regs.filter(function(r){ return r.fechaRetiro && (!f||r.fechaRetiro>=f) && (!h||r.fechaRetiro<=h); });\n    var m = {}, cam = new Set(), cont = new Set(), d = 0;\n    rs.forEach(function(r){\n      var g = m[r.fechaRetiro] || (m[r.fechaRetiro] = {refs:0,d:0,cam:new Set(),cont:new Set()});\n      g.refs++; if(r.descargado){ g.d++; d++; }\n      var uk = unitKey(r);\n      if(uk){ (r.tipo===\"camion\"?g.cam:g.cont).add(uk); (r.tipo===\"camion\"?cam:cont).add(uk); }\n    });\n    var days = Object.keys(m).sort().reverse();\n    var title = f&&h ? \"Del \"+fmt(f)+\" al \"+fmt(h) : f ? \"Desde el \"+fmt(f) : \"Hasta el \"+fmt(h);\n    box.innerHTML = '<div class=\"panel day\"><div class=\"day-head\"><h2>'+esc(title)+'</h2><div class=\"day-nums\">'+\n      '<span class=\"num red\"><b>'+cam.size+'</b> camiones 8 ton</span>'+\n      '<span class=\"num\"><b>'+cont.size+'</b> contenedores</span>'+\n      '<span class=\"num\"><b>'+rs.length+'</b> referencias</span>'+\n      '<span class=\"num okn\"><b>'+d+'</b> descargadas</span></div></div>'+\n      (days.length ? '<div class=\"units\">'+days.map(function(k){\n        var g = m[k], full = g.d===g.refs;\n        return '<button type=\"button\" class=\"unit dayb'+(full?\" full\":\"\")+'\" data-oneday=\"'+k+'\"><div class=\"unit-h\"><h3>'+esc(fmt(k))+'</h3>'+\n          (full?'<span class=\"ok\">✓ Completo</span>':'<span class=\"hint2\">'+g.d+'/'+g.refs+'</span>')+'</div>'+\n          '<div class=\"prog\"><i style=\"width:'+Math.round(g.d/g.refs*100)+'%\"></i></div>'+\n          '<p class=\"hint2\">'+g.cam.size+(g.cam.size===1?\" camión\":\" camiones\")+' · '+g.cont.size+(g.cont.size===1?\" contenedor\":\" contenedores\")+' · '+g.refs+' ref.</p></button>';\n      }).join(\"\")+'</div><p class=\"note\" style=\"padding:10px 0 0\">Toca un día para ver el detalle por camión y contenedor.</p>' : '<p class=\"note\" style=\"padding:0\">No hay retiros en este rango.</p>')+\n      '</div>';\n  }\n\n  function renderDay(){\n    var f = $(\"fdate\").value, h = $(\"fhasta\").value, box = $(\"day\");\n    if(!f && !h){ box.innerHTML=\"\"; return; }\n    if(!(f && h && f===h)){ renderRange(f, h, box); return; }\n    var day = regs.filter(function(r){ return r.fechaRetiro===f; });\n    var cam = unitsFor(f,\"camion\").list, cont = unitsFor(f,\"contenedor\").list;\n    var sinRefs = day.filter(function(r){ return !unitKey(r); });\n    var dDay = day.filter(function(r){ return r.descargado; }).length;\n    var units = cam.map(function(x){ return {t:\"camion\",x:x}; }).concat(cont.map(function(x){ return {t:\"contenedor\",x:x}; }));\n    function card(title, cls, refs, key){\n      var d = refs.filter(function(r){ return r.descargado; }).length, full = refs.length && d===refs.length;\n      return '<div class=\"unit '+cls+(full?\" full\":\"\")+'\"><div class=\"unit-h\"><h3>'+esc(title)+'</h3>'+\n        (full?'<span class=\"ok\">✓ Completo</span>':'<span class=\"hint2\">'+d+'/'+refs.length+'</span>')+\n        '<button class=\"btn sm plain\" type=\"button\" data-selunit=\"'+esc(key)+'\">Seleccionar</button></div>'+\n        '<div class=\"prog\"><i style=\"width:'+(refs.length?Math.round(d/refs.length*100):0)+'%\"></i></div>'+\n        '<div class=\"pills\">'+refs.map(function(r){ return '<button type=\"button\" class=\"pill'+(r.descargado?\" d\":\"\")+'\" data-desc=\"'+esc(r.id)+'\" title=\"'+(r.descargado?\"Descargada en CD · toca para revertir\":\"Toca para confirmar descarga\")+'\">'+esc(r.referencia)+'</button>'; }).join(\"\")+'</div></div>';\n    }\n    box.innerHTML = '<div class=\"panel day\"><div class=\"day-head\"><h2>Retiro del '+esc(fmt(f))+'</h2><div class=\"day-nums\">'+\n      '<span class=\"num red\"><b>'+cam.length+'</b> camiones 8 ton</span>'+\n      '<span class=\"num\"><b>'+cont.length+'</b> contenedores</span>'+\n      '<span class=\"num\"><b>'+day.length+'</b> referencias</span>'+\n      '<span class=\"num okn\"><b>'+dDay+'</b> descargadas</span>'+\n      '</div></div>'+\n      (units.length || sinRefs.length ? '<div class=\"units\">'+\n        units.map(function(u){ return card(unitLabel(u.t,u.x.n), u.t===\"contenedor\"?\"cont\":\"\", u.x.refs, f+\"|\"+u.t+\"|\"+u.x.n); }).join(\"\")+\n        (sinRefs.length ? card(\"Sin transporte asignado\",\"none\",sinRefs,\"none|\"+f) : \"\")+\n        '</div><p class=\"note\" style=\"padding:10px 0 0\">Toca una referencia para confirmar (o revertir) su descarga en el CD.</p>' : '<p class=\"note\" style=\"padding:0\">No hay referencias para este día.</p>')+\n      '</div>';\n  }\n\n  function thS(key, label, cls){\n    var ar = sortKey===key ? '<span class=\"ar\">'+(sortDir>0?\"▲\":\"▼\")+'</span>' : \"\";\n    return '<th data-sort=\"'+key+'\"'+(cls?' class=\"'+cls+'\"':'')+' aria-sort=\"'+(sortKey===key?(sortDir>0?\"ascending\":\"descending\"):\"none\")+'\">'+label+ar+'</th>';\n  }\n  function renderRecords(){\n    var rows = filtered();\n    var head = '<thead><tr><th><input type=\"checkbox\" class=\"chk\" id=\"chk-all\" aria-label=\"Seleccionar todo\"></th>'+\n      thS(\"embarque\",\"Embarque\")+thS(\"referencia\",\"Referencia\")+thS(\"almacenadora\",\"Almacenadora\")+thS(\"fechaDocs\",\"Entrega docs.\")+\n      thS(\"fechaRetiro\",\"Fecha retiro\")+thS(\"bodega\",\"Bodega\")+thS(\"transporte\",\"Transporte\")+thS(\"estado\",\"Descarga en CD\")+'<th></th></tr></thead>';\n    if(!rows.length){\n      var hidden = regs.length && stFilter!==\"all\" && baseFiltered().length>0;\n      var msg = !regs.length ? '<strong>Aún no hay registros</strong>Pulsa “+ Nuevo registro” para empezar.' :\n        hidden ? '<strong>No hay referencias '+(stFilter===\"p\"?\"pendientes\":\"descargadas\")+' con este filtro</strong>Hay '+baseFiltered().length+' referencia(s) en total.<br><button class=\"btn sm ghost\" type=\"button\" data-st=\"all\" style=\"margin-top:10px\">Ver todas</button>' :\n        (($(\"fdate\").value || $(\"fhasta\").value) ? '<strong>No hay referencias en las fechas seleccionadas</strong><button class=\"btn sm ghost\" type=\"button\" data-allfechas style=\"margin-top:10px\">Ver todas las fechas</button>' : '<strong>Sin resultados</strong>Ajusta la búsqueda.');\n      $(\"tbl\").innerHTML = head + '<tbody><tr><td colspan=\"10\"><div class=\"empty\">'+msg+'</div></td></tr></tbody>';\n      $(\"cards\").innerHTML = '<div class=\"empty\">'+msg+'</div>';\n    } else {\n      $(\"tbl\").innerHTML = head + '<tbody>' + rows.map(function(r){\n        var cls = (r.descargado?\"d\":\"\")+(flash.has(r.id)?\" flash\":\"\");\n        return '<tr class=\"'+cls+'\"><td><input type=\"checkbox\" class=\"chk\" data-sel=\"'+esc(r.id)+'\"'+(sel.has(r.id)?\" checked\":\"\")+' aria-label=\"Seleccionar '+esc(r.referencia)+'\"></td>'+\n          '<td>'+esc(r.embarque||\"—\")+'</td><td class=\"ref\">'+esc(r.referencia)+'</td><td>'+esc(r.almacenadora||\"—\")+'</td>'+\n          '<td>'+esc(fmt(r.fechaDocs))+'</td><td>'+esc(fmt(r.fechaRetiro))+'</td><td>'+esc(r.bodega||\"—\")+'</td><td>'+tagHtml(r)+'</td><td>'+stHtml(r)+'</td>'+\n          '<td style=\"white-space:nowrap\"><button class=\"icon-btn\" data-edit=\"'+esc(r.id)+'\" title=\"Editar\" aria-label=\"Editar\">✎</button><button class=\"icon-btn del\" data-del=\"'+esc(r.id)+'\" title=\"Eliminar\" aria-label=\"Eliminar\">✕</button></td></tr>';\n      }).join(\"\") + '</tbody>';\n      $(\"cards\").innerHTML = rows.map(function(r){\n        var cls = (r.descargado?\" d\":\"\")+(flash.has(r.id)?\" flash\":\"\");\n        return '<div class=\"card'+cls+'\"><input type=\"checkbox\" class=\"chk\" data-sel=\"'+esc(r.id)+'\"'+(sel.has(r.id)?\" checked\":\"\")+' aria-label=\"Seleccionar\">'+\n          '<div><div class=\"ref\">'+esc(r.referencia)+'</div><div style=\"margin-top:2px\">'+tagHtml(r)+'</div></div>'+\n          '<div class=\"acts\"><button class=\"icon-btn\" data-edit=\"'+esc(r.id)+'\" aria-label=\"Editar\">✎</button><button class=\"icon-btn del\" data-del=\"'+esc(r.id)+'\" aria-label=\"Eliminar\">✕</button></div>'+\n          '<div class=\"meta\"><span>Embarque: <b>'+esc(r.embarque||\"—\")+'</b></span><span>Bodega: <b>'+esc(r.bodega||\"—\")+'</b></span>'+\n          '<span>Almacenadora: <b>'+esc(r.almacenadora||\"—\")+'</b></span><span>Retiro: <b>'+esc(fmt(r.fechaRetiro))+'</b></span>'+\n          '<span>Entrega docs.: <b>'+esc(fmt(r.fechaDocs))+'</b></span></div><div class=\"stw\">'+stHtml(r)+'</div></div>';\n      }).join(\"\");\n    }\n    var all = $(\"chk-all\");\n    if(all){ all.checked = rows.length>0 && rows.every(function(r){ return sel.has(r.id); }); }\n    renderSelbar();\n  }\n  function renderSelbar(){\n    sel.forEach(function(id){ if(!regs.some(function(r){ return r.id===id; })) sel.delete(id); });\n    $(\"selbar\").classList.toggle(\"hidden\", sel.size===0);\n    $(\"selcount\").textContent = sel.size + (sel.size===1 ? \" seleccionada\" : \" seleccionadas\");\n  }\n  function renderLists(){\n    function uniq(k){ return Array.from(new Set(regs.map(function(r){ return (r[k]||\"\").trim(); }).filter(Boolean))).sort(); }\n    $(\"dl-alm\").innerHTML = uniq(\"almacenadora\").map(function(v){ return '<option value=\"'+esc(v)+'\">'; }).join(\"\");\n    $(\"dl-bod\").innerHTML = uniq(\"bodega\").map(function(v){ return '<option value=\"'+esc(v)+'\">'; }).join(\"\");\n  }\n\n  /* ---------- Stats ---------- */\n  function statsRows(){\n    var from = $(\"s-from\").value, to = $(\"s-to\").value;\n    return regs.filter(function(r){ return r.fechaRetiro && (!from || r.fechaRetiro>=from) && (!to || r.fechaRetiro<=to); });\n  }\n  function statsData(){\n    var rs = statsRows();\n    function group(keyFn){\n      var m = {};\n      rs.forEach(function(r){\n        var k = keyFn(r) || \"(Sin dato)\";\n        var g = m[k] || (m[k] = { k:k, refs:0, d:0, cam:new Set(), cont:new Set(), sin:0 });\n        g.refs++; if(r.descargado) g.d++;\n        var uk = unitKey(r);\n        if(uk) (r.tipo===\"camion\" ? g.cam : g.cont).add(uk); else g.sin++;\n      });\n      return Object.keys(m).map(function(k){ var g=m[k]; return { k:k, refs:g.refs, d:g.d, cam:g.cam.size, cont:g.cont.size, tot:g.cam.size+g.cont.size, sin:g.sin }; });\n    }\n    var all = group(function(){ return \"Total\"; })[0] || { refs:0, d:0, cam:0, cont:0, tot:0, sin:0 };\n    return {\n      all: all,\n      fecha: group(function(r){ return r.fechaRetiro; }).sort(function(a,b){ return a.k<b.k?1:-1; }),\n      alm: group(function(r){ return (r.almacenadora||\"\").trim(); }).sort(function(a,b){ return b.refs-a.refs || a.k.localeCompare(b.k); }),\n      bod: group(function(r){ return (r.bodega||\"\").trim(); }).sort(function(a,b){ return b.refs-a.refs || a.k.localeCompare(b.k); })\n    };\n  }\n  function pctCell(g){\n    var p = g.refs ? Math.round(g.d/g.refs*100) : 0;\n    return '<span class=\"pct\"><span class=\"prog\"><i style=\"width:'+p+'%\"></i></span>'+g.d+'/'+g.refs+'</span>';\n  }\n  function statTable(rows, label, kind, total){\n    var head = '<thead><tr><th>'+label+'</th><th class=\"n\">Referencias</th><th class=\"n\">Camiones 8 ton</th><th class=\"n\">Contenedores</th><th>Total unidades</th><th class=\"n\">Descargadas en CD</th><th class=\"n\">Sin transporte</th></tr></thead>';\n    if(!rows.length) return head + '<tbody><tr><td colspan=\"7\"><div class=\"empty\">Sin retiros en el periodo.</div></td></tr></tbody>';\n    var max = Math.max.apply(null, rows.map(function(g){ return g.tot; }).concat([1]));\n    var body = rows.map(function(g){\n      var attr = kind===\"fecha\" ? ' data-goto-date=\"'+esc(g.k)+'\"' : (g.k!==\"(Sin dato)\" ? ' data-goto-q=\"'+esc(g.k)+'\"' : \"\");\n      return '<tr class=\"'+(attr?\"click\":\"\")+'\"'+attr+' title=\"'+(attr?\"Ver registros\":\"\")+'\"><td>'+esc(kind===\"fecha\"?fmt(g.k):g.k)+'</td><td class=\"n\">'+g.refs+'</td><td class=\"n\">'+g.cam+'</td><td class=\"n\">'+g.cont+'</td>'+\n        '<td><span class=\"minibar\" style=\"width:'+Math.max(4,Math.round(g.tot/max*90))+'px\"></span><b>'+g.tot+'</b></td><td class=\"n\">'+pctCell(g)+'</td><td class=\"n\">'+(g.sin||\"—\")+'</td></tr>';\n    }).join(\"\");\n    if(total) body += '<tr class=\"total\"><td>Total</td><td class=\"n\">'+total.refs+'</td><td class=\"n\">'+total.cam+'</td><td class=\"n\">'+total.cont+'</td><td><b>'+total.tot+'</b></td><td class=\"n\">'+pctCell(total)+'</td><td class=\"n\">'+(total.sin||\"—\")+'</td></tr>';\n    return head + '<tbody>'+body+'</tbody>';\n  }\n  function renderChart(rows){\n    var data = rows.slice().sort(function(a,b){ return a.k<b.k?-1:1; });\n    if(!data.length){ $(\"chart\").innerHTML = '<div class=\"empty\">Sin retiros en el periodo.</div>'; return; }\n    var max = Math.max.apply(null, data.map(function(g){ return g.tot; }).concat([1]));\n    var H = 150;\n    $(\"chart\").innerHTML = '<div class=\"bars\">'+data.map(function(g){\n      var h1 = Math.round(g.cam/max*H), h2 = Math.round(g.cont/max*H);\n      return '<button type=\"button\" class=\"bcol\" data-goto-date=\"'+esc(g.k)+'\" data-tip=\"'+esc(fmt(g.k)+\"|\"+g.cam+\"|\"+g.cont+\"|\"+g.refs+\"|\"+g.d)+'\" aria-label=\"'+esc(fmt(g.k))+': '+g.tot+' unidades\">'+\n        '<span class=\"v\">'+g.tot+'</span><span class=\"bstack\" style=\"height:'+(h1+h2)+'px\"><i class=\"c1\" style=\"height:'+h1+'px\"></i><i class=\"c2\" style=\"height:'+h2+'px\"></i></span></button>';\n    }).join(\"\")+'</div><div class=\"blab\">'+data.map(function(g){ return '<span>'+esc(fmtShort(g.k))+'</span>'; }).join(\"\")+'</div>';\n  }\n  function renderStats(){\n    var s = statsData(), p = s.all.refs ? Math.round(s.all.d/s.all.refs*100) : 0;\n    $(\"kpis\").innerHTML =\n      '<div class=\"panel kpi\"><b>'+s.all.refs+'</b><span>Referencias retiradas</span></div>'+\n      '<div class=\"panel kpi red\"><b>'+s.all.cam+'</b><span>Camiones 8 ton</span></div>'+\n      '<div class=\"panel kpi\"><b>'+s.all.cont+'</b><span>Contenedores</span></div>'+\n      '<div class=\"panel kpi red\"><b>'+s.all.tot+'</b><span>Total unidades</span></div>'+\n      '<div class=\"panel kpi okk wide\"><b>'+p+'%</b><span>Descargado en CD ('+s.all.d+' de '+s.all.refs+')</span><div class=\"prog\"><i style=\"width:'+p+'%\"></i></div></div>';\n    renderChart(s.fecha);\n    $(\"t-fecha\").innerHTML = statTable(s.fecha, \"Fecha de retiro\", \"fecha\", s.all);\n    $(\"t-alm\").innerHTML = statTable(s.alm, \"Almacenadora\", \"alm\");\n    $(\"t-bod\").innerHTML = statTable(s.bod, \"Bodega\", \"bod\");\n    Array.prototype.forEach.call(document.querySelectorAll(\"#qr button\"), function(b){ b.classList.toggle(\"on\", b.dataset.range===qRange); });\n  }\n\n  function render(){\n    renderLists();\n    if(view===\"reg\"){ renderSeg(); renderRecords(); } else { renderStats(); }\n  }\n\n  /* ---------- Modals ---------- */\n  function closeModal(){ $(\"modal-root\").innerHTML = \"\"; }\n  function openModal(title, bodyHtml, footHtml){\n    $(\"modal-root\").innerHTML = '<div class=\"ov\" id=\"ov\"><div class=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"'+esc(title)+'\">'+\n      '<header><h2>'+esc(title)+'</h2><button class=\"icon-btn\" id=\"m-x\" aria-label=\"Cerrar\" type=\"button\">✕</button></header>'+\n      '<div class=\"body\">'+bodyHtml+'</div><footer>'+footHtml+'</footer></div></div>';\n    $(\"m-x\").onclick = closeModal;\n    $(\"ov\").addEventListener(\"mousedown\", function(e){ if(e.target.id===\"ov\") closeModal(); });\n  }\n  document.addEventListener(\"keydown\", function(e){ if(e.key===\"Escape\") closeModal(); });\n\n  function openForm(rec){\n    var r = rec || {};\n    openModal(rec ? \"Editar registro\" : \"Nuevo registro\",\n      '<label class=\"f\">Embarque<input type=\"text\" id=\"m-emb\" value=\"'+esc(r.embarque)+'\"></label>'+\n      '<label class=\"f\">Referencia *<input type=\"text\" id=\"m-ref\" value=\"'+esc(r.referencia)+'\" required></label>'+\n      '<label class=\"f\">Almacenadora<input type=\"text\" id=\"m-alm\" list=\"dl-alm\" value=\"'+esc(r.almacenadora)+'\"></label>'+\n      '<label class=\"f\">Bodega<input type=\"text\" id=\"m-bod\" list=\"dl-bod\" value=\"'+esc(r.bodega)+'\"></label>'+\n      '<label class=\"f\">Fecha entrega de documentación<input type=\"date\" id=\"m-fdoc\" value=\"'+esc(r.fechaDocs)+'\"></label>'+\n      '<label class=\"f\">Fecha de retiro<input type=\"date\" id=\"m-fret\" value=\"'+esc(r.fechaRetiro || ($(\"fdate\").value && $(\"fdate\").value===$(\"fhasta\").value ? $(\"fdate\").value : \"\"))+'\"></label>'+\n      '<fieldset class=\"fieldset\"><legend>Transporte</legend>'+\n        '<label class=\"f\">Tipo<select id=\"m-tipo\"><option value=\"\">Sin asignar</option><option value=\"camion\"'+(r.tipo===\"camion\"?\" selected\":\"\")+'>Camión 8 ton</option><option value=\"contenedor\"'+(r.tipo===\"contenedor\"?\" selected\":\"\")+'>Contenedor</option></select></label>'+\n        '<label class=\"f\">Unidad<select id=\"m-uni\"></select></label>'+\n        '<p class=\"hint\" id=\"m-uhint\"></p>'+\n      '</fieldset>'+\n      '<fieldset class=\"fieldset'+(r.descargado?\" okf\":\"\")+'\" id=\"m-dfs\"><legend>Centro de distribución</legend>'+\n        '<label class=\"switch\"><input type=\"checkbox\" id=\"m-desc\"'+(r.descargado?\" checked\":\"\")+'> Descargado en CD</label>'+\n        '<label class=\"f\">Fecha de descarga<input type=\"date\" id=\"m-fdes\" value=\"'+esc(r.fechaDescarga)+'\"'+(r.descargado?\"\":\" disabled\")+'></label>'+\n      '</fieldset>'+\n      '<p class=\"err hidden\" id=\"m-err\"></p>',\n      '<button class=\"btn plain\" id=\"m-cancel\" type=\"button\">Cancelar</button><button class=\"btn\" id=\"m-save\" type=\"button\">Guardar</button>');\n    function uhint(){\n      var h=$(\"m-uhint\"), t=$(\"m-tipo\").value, v=$(\"m-uni\").value;\n      var nom = t===\"contenedor\" ? \"contenedor\" : \"camión\";\n      if(!t || !$(\"m-fret\").value){ h.textContent=\"Las referencias que asignes a la misma unidad el mismo día cuentan como 1 solo camión o contenedor.\"; return; }\n      if(v===\"new\"){ h.textContent=\"Esta referencia abrirá un \"+nom+\" adicional para ese día.\"; return; }\n      h.textContent=\"Se suma a un \"+nom+\" que ya existe ese día: no aumenta el conteo de unidades.\";\n    }\n    function syncUnit(){\n      var t=$(\"m-tipo\").value, f=$(\"m-fret\").value, u=$(\"m-uni\");\n      if(!t || !f){ u.innerHTML='<option value=\"\">'+(t?\"Primero indica la fecha de retiro\":\"—\")+'</option>'; u.disabled=true; uhint(); return; }\n      u.disabled=false;\n      var keep = (rec && rec.tipo===t && rec.fechaRetiro===f) ? rec.unidad : null;\n      u.innerHTML = unitOptions(f, t, keep);\n      uhint();\n    }\n    $(\"m-uni\").onchange = uhint; $(\"m-tipo\").onchange = syncUnit; $(\"m-fret\").onchange = syncUnit; syncUnit();\n    $(\"m-desc\").onchange = function(){\n      var on = this.checked; $(\"m-fdes\").disabled = !on; $(\"m-dfs\").classList.toggle(\"okf\", on);\n      if(on && !$(\"m-fdes\").value) $(\"m-fdes\").value = today();\n    };\n    $(\"m-cancel\").onclick = closeModal;\n    $(\"m-ref\").focus();\n    $(\"m-save\").onclick = function(){\n      var err=$(\"m-err\"), ref=$(\"m-ref\").value.trim(), tipo=$(\"m-tipo\").value, fret=$(\"m-fret\").value;\n      if(!ref){ err.textContent=\"La referencia es obligatoria.\"; err.classList.remove(\"hidden\"); return; }\n      if(tipo && !fret){ err.textContent=\"Indica la fecha de retiro para asignar transporte.\"; err.classList.remove(\"hidden\"); return; }\n      var uv=$(\"m-uni\").value, unidad=null;\n      if(tipo){ unidad = uv===\"new\" ? unitsFor(fret,tipo).next : parseInt(uv,10); }\n      var dsc = $(\"m-desc\").checked;\n      var body = {\n        embarque:$(\"m-emb\").value.trim(), referencia:ref, almacenadora:$(\"m-alm\").value.trim(), bodega:$(\"m-bod\").value.trim(),\n        fechaDocs:$(\"m-fdoc\").value||\"\", fechaRetiro:fret||\"\", tipo:tipo||null, unidad:unidad,\n        descargado:dsc, fechaDescarga: dsc ? ($(\"m-fdes\").value || today()) : \"\",\n        creado:(rec && rec.creado) || new Date().toISOString(), actualizado:new Date().toISOString()\n      };\n      var btn = this; btn.disabled = true;\n      var id = rec ? rec.id : newId();\n      flash.add(id);\n      put(id, body).then(function(){ closeModal(); toast(rec?\"Registro actualizado\":\"Registro guardado\"); setTimeout(function(){ flash.clear(); }, 950); }).catch(function(){ btn.disabled=false; });\n    };\n  }\n\n  function openAssign(){\n    var chosen = regs.filter(function(r){ return sel.has(r.id); });\n    var fechas = Array.from(new Set(chosen.map(function(r){ return r.fechaRetiro||\"\"; })));\n    var problem = fechas.indexOf(\"\")>=0 ? \"Todas las referencias seleccionadas necesitan fecha de retiro.\" :\n                  fechas.length>1 ? \"Las referencias seleccionadas tienen fechas de retiro distintas. Una unidad solo puede ser de un día.\" : \"\";\n    var f = fechas[0];\n    openModal(\"Asignar transporte\",\n      '<p class=\"hint full\"><b>'+chosen.length+'</b> referencia(s): '+chosen.map(function(r){ return esc(r.referencia); }).join(\", \")+'</p>'+\n      (problem ? '<p class=\"err\">'+esc(problem)+'</p>' :\n        '<p class=\"hint full\">Fecha de retiro: <b>'+esc(fmt(f))+'</b></p>'+\n        '<label class=\"f\">Tipo<select id=\"a-tipo\"><option value=\"camion\">Camión 8 ton</option><option value=\"contenedor\">Contenedor</option></select></label>'+\n        '<label class=\"f\">Unidad<select id=\"a-uni\"></select></label>'+\n        '<p class=\"hint\">Todas estas referencias contarán como <b>una sola unidad</b> ese día.</p>'),\n      problem ? '<button class=\"btn\" id=\"a-close\" type=\"button\">Entendido</button>' :\n        '<button class=\"btn plain\" id=\"a-clear\" type=\"button\">Quitar transporte</button><button class=\"btn\" id=\"a-ok\" type=\"button\">Asignar</button>');\n    if(problem){ $(\"a-close\").onclick = closeModal; return; }\n    function sync(){ $(\"a-uni\").innerHTML = unitOptions(f, $(\"a-tipo\").value, null); }\n    $(\"a-tipo\").onchange = sync; sync();\n    async function apply(tipo, unidad){\n      try{\n        for(var i=0;i<chosen.length;i++){\n          var r = chosen[i], body = bodyOf(r);\n          body.tipo = tipo; body.unidad = unidad; body.actualizado = new Date().toISOString();\n          flash.add(r.id);\n          await put(r.id, body);\n        }\n        sel.clear(); closeModal(); render();\n        setTimeout(function(){ flash.clear(); }, 950);\n        toast(tipo ? \"Asignadas a \"+unitLabel(tipo,unidad) : \"Transporte retirado\");\n      }catch(e){}\n    }\n    $(\"a-ok\").onclick = function(){ var t=$(\"a-tipo\").value, v=$(\"a-uni\").value; this.disabled = true; apply(t, v===\"new\" ? unitsFor(f,t).next : parseInt(v,10)); };\n    $(\"a-clear\").onclick = function(){ this.disabled = true; apply(null, null); };\n  }\n\n  function confirmDelete(id){\n    var r = regs.find(function(x){ return x.id===id; }); if(!r) return;\n    openModal(\"Eliminar registro\", '<p class=\"hint full\" style=\"font-size:15px;color:var(--ink)\">¿Eliminar la referencia <b>'+esc(r.referencia)+'</b>? Esta acción no se puede deshacer.</p>',\n      '<button class=\"btn plain\" id=\"d-no\" type=\"button\">Cancelar</button><button class=\"btn\" id=\"d-yes\" type=\"button\">Eliminar</button>');\n    $(\"d-no\").onclick = closeModal;\n    $(\"d-yes\").onclick = function(){ sel.delete(id); del(id).then(function(){ closeModal(); toast(\"Registro eliminado\"); }); };\n  }\n\n  /* ---------- CSV ---------- */\n  function csvCell(v){ v = String(v==null?\"\":v); return /[\",;\\n]/.test(v) ? '\"'+v.replace(/\"/g,'\"\"')+'\"' : v; }\n  async function exportCsv(){\n    var s = statsData(), lines = [];\n    function block(title, rows, isDate){\n      lines.push(csvCell(title));\n      lines.push([\"Grupo\",\"Referencias\",\"Camiones 8 ton\",\"Contenedores\",\"Total unidades\",\"Descargadas en CD\",\"Sin transporte\"].join(\",\"));\n      rows.forEach(function(g){ lines.push([csvCell(isDate?fmt(g.k):g.k), g.refs, g.cam, g.cont, g.tot, g.d, g.sin].join(\",\")); });\n      lines.push(\"\");\n    }\n    block(\"Por fecha de retiro\", s.fecha, true); block(\"Por almacenadora\", s.alm, false); block(\"Por bodega\", s.bod, false);\n    lines.push(\"Detalle de referencias\");\n    lines.push([\"Embarque\",\"Referencia\",\"Almacenadora\",\"Fecha entrega documentación\",\"Fecha retiro\",\"Bodega\",\"Transporte\",\"Descargado en CD\",\"Fecha descarga\"].join(\",\"));\n    statsRows().forEach(function(r){\n      lines.push([r.embarque,r.referencia,r.almacenadora,fmt(r.fechaDocs),fmt(r.fechaRetiro),r.bodega,(r.tipo&&r.unidad)?unitLabel(r.tipo,r.unidad):\"Sin asignar\",r.descargado?\"Sí\":\"No\",r.fechaDescarga?fmt(r.fechaDescarga):\"\"].map(csvCell).join(\",\"));\n    });\n    var blob = new Blob([\"\\ufeff\"+lines.join(\"\\n\")], {type:\"text/csv\"});\n    if(!downloads){ var a=document.createElement(\"a\"); a.href=URL.createObjectURL(blob); a.download=\"estadisticas-retiros.csv\"; document.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 500); return; }\n    try{ await downloads.save({ filename:\"estadisticas-retiros.csv\", data:blob }); }\n    catch(e){ if(!e || e.code!==\"declined\") toast(\"No se pudo exportar el archivo.\"); }\n  }\n\n  /* ---------- Events ---------- */\n  function setView(v){\n    view = v;\n    $(\"v-reg\").classList.toggle(\"hidden\", v!==\"reg\");\n    $(\"v-est\").classList.toggle(\"hidden\", v!==\"est\");\n    $(\"nav-reg\").classList.toggle(\"ghost\", v!==\"reg\");\n    $(\"nav-est\").classList.toggle(\"ghost\", v!==\"est\");\n    hideTip(); render(); window.scrollTo(0,0);\n  }\n  $(\"nav-reg\").onclick = function(){ setView(\"reg\"); };\n  $(\"nav-est\").onclick = function(){ setView(\"est\"); };\n  $(\"btn-new\").onclick = function(){ openForm(null); };\n  $(\"q\").oninput = render;\n  $(\"fdate\").onchange = function(){ var f=$(\"fdate\").value, h=$(\"fhasta\").value; if(f && (!h || h<f)) $(\"fhasta\").value=f; stFilter=\"all\"; sel.clear(); render(); };\n  $(\"fhasta\").onchange = function(){ var f=$(\"fdate\").value, h=$(\"fhasta\").value; if(h && f && f>h) $(\"fdate\").value=h; stFilter=\"all\"; sel.clear(); render(); };\n  $(\"btn-hoy\").onclick = function(){ $(\"fdate\").value=today(); $(\"fhasta\").value=today(); stFilter=\"all\"; sel.clear(); render(); };\n  $(\"btn-clear\").onclick = function(){ $(\"q\").value=\"\"; $(\"fdate\").value=\"\"; $(\"fhasta\").value=\"\"; stFilter=\"all\"; sel.clear(); render(); };\n  $(\"btn-assign\").onclick = openAssign;\n  $(\"btn-markd\").onclick = function(){ var ids=Array.from(sel); sel.clear(); setDescargado(ids, true); render(); };\n  $(\"btn-markp\").onclick = function(){ var ids=Array.from(sel); sel.clear(); setDescargado(ids, false); render(); };\n  $(\"btn-unsel\").onclick = function(){ sel.clear(); render(); };\n  $(\"s-from\").onchange = function(){ qRange=\"\"; render(); };\n  $(\"s-to\").onchange = function(){ qRange=\"\"; render(); };\n  $(\"s-csv\").onclick = exportCsv;\n\n  $(\"v-reg\").addEventListener(\"click\", function(e){\n    var t = e.target;\n    if(t.id===\"chk-all\"){ filtered().forEach(function(r){ if(t.checked) sel.add(r.id); else sel.delete(r.id); }); renderRecords(); return; }\n    var s = t.getAttribute && t.getAttribute(\"data-sel\");\n    if(s){ if(t.checked) sel.add(s); else sel.delete(s); renderRecords(); return; }\n    var b = t.closest && t.closest(\"[data-edit],[data-del],[data-desc],[data-selunit],[data-chip],[data-st],[data-oneday],[data-allfechas],th[data-sort]\");\n    if(!b) return;\n    if(b.dataset.desc){ var r0 = regs.find(function(x){ return x.id===b.dataset.desc; }); if(r0) setDescargado([r0.id], !r0.descargado); return; }\n    if(b.hasAttribute(\"data-chip\")){ var cv=b.dataset.chip; $(\"fdate\").value = ($(\"fdate\").value===cv && cv) ? \"\" : cv; stFilter=\"all\"; sel.clear(); render(); return; }\n    if(b.dataset.st){ stFilter = b.dataset.st; render(); return; }\n    if(b.dataset.oneday){ $(\"fdate\").value=b.dataset.oneday; $(\"fhasta\").value=b.dataset.oneday; stFilter=\"all\"; sel.clear(); render(); return; }\n    if(b.hasAttribute(\"data-allfechas\")){ $(\"fdate\").value=\"\"; $(\"fhasta\").value=\"\"; stFilter=\"all\"; sel.clear(); render(); return; }\n    if(b.dataset.sort){ var k=b.dataset.sort; if(sortKey===k) sortDir=-sortDir; else { sortKey=k; sortDir = (k===\"fechaRetiro\"||k===\"fechaDocs\")?-1:1; } renderRecords(); return; }\n    if(b.dataset.selunit){\n      var key = b.dataset.selunit, ids;\n      if(key.indexOf(\"none|\")===0){ var fd=key.slice(5); ids = regs.filter(function(r){ return r.fechaRetiro===fd && !unitKey(r); }); }\n      else ids = regs.filter(function(r){ return unitKey(r)===key; });\n      var allIn = ids.every(function(r){ return sel.has(r.id); });\n      ids.forEach(function(r){ if(allIn) sel.delete(r.id); else sel.add(r.id); });\n      renderRecords(); return;\n    }\n    if(b.dataset.edit){ var r = regs.find(function(x){ return x.id===b.dataset.edit; }); if(r) openForm(r); return; }\n    if(b.dataset.del) confirmDelete(b.dataset.del);\n  });\n\n  $(\"v-est\").addEventListener(\"click\", function(e){\n    var b = e.target.closest && e.target.closest(\"[data-goto-date],[data-goto-q],[data-range]\");\n    if(!b) return;\n    if(b.dataset.range){\n      qRange = b.dataset.range;\n      if(qRange===\"all\"){ $(\"s-from\").value=\"\"; $(\"s-to\").value=\"\"; }\n      else if(qRange===\"mes\"){ var t=today(); $(\"s-from\").value=t.slice(0,8)+\"01\"; $(\"s-to\").value=t; }\n      else { $(\"s-from\").value=today(-(parseInt(qRange,10)-1)); $(\"s-to\").value=today(); }\n      render(); return;\n    }\n    if(b.dataset.gotoDate){ $(\"q\").value=\"\"; $(\"fdate\").value=b.dataset.gotoDate; $(\"fhasta\").value=b.dataset.gotoDate; stFilter=\"all\"; sel.clear(); setView(\"reg\"); return; }\n    if(b.dataset.gotoQ){ $(\"q\").value=b.dataset.gotoQ; $(\"fdate\").value=\"\"; $(\"fhasta\").value=\"\"; stFilter=\"all\"; sel.clear(); setView(\"reg\"); }\n  });\n\n  /* Tooltip on chart bars */\n  var tip = null;\n  function hideTip(){ if(tip){ tip.remove(); tip=null; } }\n  $(\"chart\").addEventListener(\"pointerover\", function(e){\n    var b = e.target.closest(\".bcol\"); if(!b) return;\n    var p = b.dataset.tip.split(\"|\");\n    hideTip(); tip = document.createElement(\"div\"); tip.className=\"tip\";\n    tip.textContent = p[0]+\" — \"+p[1]+\" camión(es), \"+p[2]+\" contenedor(es) · \"+p[3]+\" ref., \"+p[4]+\" descargadas\";\n    document.body.appendChild(tip);\n    var r = b.getBoundingClientRect(), w = tip.offsetWidth;\n    tip.style.left = Math.max(8, Math.min(window.innerWidth-w-8, r.left + r.width/2 - w/2))+\"px\";\n    tip.style.top = Math.max(8, r.top - tip.offsetHeight - 6)+\"px\";\n  });\n  $(\"chart\").addEventListener(\"pointerout\", function(e){ if(e.target.closest(\".bcol\")) hideTip(); });\n  window.addEventListener(\"scroll\", hideTip, {passive:true});\n\n  $(\"fdate\").value = today(); $(\"fhasta\").value = today();\n  render();\n  initStore();\n})();\n</script>\n</body>\n</html>\n";
